        maximum_values = (len(maximum_preorder), *maximum_preorder, *maximum_inorder)
        add(maximum_values, MAX_CREATE_BINARY_TREE_OUTPUT_BYTES)
        add(maximum_values, MAX_CREATE_BINARY_TREE_OUTPUT_BYTES - 1)

