        cases: dict[tuple[tuple[int, ...], int, bool, bool, int], tuple[int, bytes]] = {}

        def add_soundex_case(values: tuple[int, ...], capacity: int = default_capacity,
                             output_is_null: bool = False, input_is_null: bool = False,
                             input_length: int | None = None) -> None:
            values = tuple(values)
            if input_length is None:
                input_length = len(values)
            if (len(values) > SOUNDEX_ENCODER_MAX_PARSEABLE_INPUT_LENGTH
                    or type(capacity) is not int
                    or not 0 <= capacity <= SOUNDEX_ENCODER_MAX_OUTPUT_BYTES
                    or type(output_is_null) is not bool or type(input_is_null) is not bool
                    or type(input_length) is not int
                    or not 0 <= input_length <= SOUNDEX_ENCODER_MAX_PARSEABLE_INPUT_LENGTH
                    or (input_is_null and (values or input_length == 0 or output_is_null))
                    or (not input_is_null and input_length != len(values))):
                raise ValueError("soundex_encoder generated input/output framing is out of range")
            result, output = soundex_encoder_oracle(
                values, capacity, output_is_null, input_is_null, input_length)
            if result >= 0:
                if result != len(output) or result != SOUNDEX_ENCODER_MAX_OUTPUT_BYTES:
                    raise ValueError("soundex_encoder success result does not match its four output bytes")
            elif output:
                raise ValueError("soundex_encoder errors must not write output")
