        for _ in range(128):
            initial_count = rng_stack.randint(0, LIST_BASED_STACK_MAX_INITIAL_ITEMS)
            initial_items = [rng_stack.randint(LIST_BASED_STACK_I32_MIN,
                                               LIST_BASED_STACK_I32_MAX)
                             for _item in range(initial_count)]
            stack = list(reversed(initial_items))
            operation_count = rng_stack.randint(0, LIST_BASED_STACK_MAX_OPERATIONS)
            operation_values: list[int] = []
            for _operation in range(operation_count):
                allowed = [1, 4, 5, 6]
                if stack:
                    allowed.extend((2, 3))
                opcode = rng_stack.choice(allowed)
                operation_values.append(opcode)
                if opcode == 1:
                    value = rng_stack.randint(LIST_BASED_STACK_I32_MIN,
                                              LIST_BASED_STACK_I32_MAX)
                    operation_values.append(value)
                    stack.insert(0, value)
                elif opcode == 2:
                    stack.pop(0)
                elif opcode == 5:
                    operation_values.append(rng_stack.randint(
                        LIST_BASED_STACK_I32_MIN, LIST_BASED_STACK_I32_MAX))
                elif opcode == 6:
                    stack.clear()
